package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class SupportSourcesBrowserAcceptance {
 static void click(Page p,String name){ServiceOutagesBrowserAcceptance.click(p,name);}
 static void run(BrowserTest h)throws Exception{
  String user="ContextBrowser"+id().substring(0,8),article,other,record;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",user,"password",WorkflowSupport.PASSWORD,"role","requester"));article=KnowledgeSearchAcceptance.article(db,actor,"Contextual support guidance","Check the request timeline for updates");other=KnowledgeSearchAcceptance.article(db,actor,"Service response expectations","Requests remain pending until a team starts work <script>source</script>");ApprovalTest.as(db,user);record=Requests.create(db,user,map("short_description","My equipment question","description","My request is pending <script>context</script>")).get("sys_id").toString();db.connection.commit();}
  try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.store.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   provider.settings.put("AI_SUPPORT_ENABLED","true");provider.answer.set("The supplied guidance says to check your pending request timeline <script>answer</script>");var page=context.newPage();FulfilmentBrowserAcceptance.login(h,page,user);page.navigate(h.base()+"/knowledge/"+article);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Start a support conversation")).press("Enter");page.getByLabel("Additional published article ID (optional)").fill(other);page.getByLabel("Context record table (optional)").fill("sc_request");page.getByLabel("Context record ID (optional)").fill(record);click(page,"Create private conversation");String url=page.url();assertThat(page.locator("main")).containsText("Additional supplied context");assertThat(page.locator("main")).containsText("Record revision 0");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review human follow-up"))).hasCount(0);assertThat(page.locator("main")).containsText("This transcript cannot be copied into a new request");
   page.getByLabel("Your question").fill("Why does my request still say pending?");click(page,"Preview external request");assertEquals(0,provider.calls.get());assertThat(page.locator("pre")).containsText("My request is pending <script>context</script>");assertThat(page.locator("pre")).containsText(other);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/support-sources-preview-light.png")).setFullPage(true));page.getByLabel("Send this question, history and all selected sources to the configured provider").check();click(page,"Ask with reviewed context");assertThat(page.locator("main")).containsText(provider.answer.get());assertThat(page.locator("main script")).hasCount(0);click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/support-sources-answer-dark.png")).setFullPage(true));
   page.getByLabel("Your question").fill("Where can I follow up?");click(page,"Preview external request");assertThat(page.locator("pre")).containsText("Why does my request still say pending?");page.getByLabel("Send this question, history and all selected sources to the configured provider").check();click(page,"Ask with reviewed context");assertEquals(2,provider.calls.get());assertTrue(context.request().get(url+"/export").text().contains(record));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("sc_request / "+record)).press("Enter");assertThat(page.locator("main")).containsText("My equipment question");
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}page.navigate(url);assertThat(page.locator("main")).not().containsText(provider.answer.get());assertEquals(404,context.request().get(url+"/export").status());page.navigate(h.base()+"/support");page.getByLabel("Delete this conversation permanently").check();click(page,"Delete conversation");assertThat(page.locator("main")).containsText("No retained conversations");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/support-sources-deleted-dark.png")).setFullPage(true));assertEquals(2,provider.calls.get());
  }
 }
}
